# Load KEGG mapping genes
kegg_genes = set()
with open('/workspace/pau_kegg_mapping.tsv') as f:
    next(f)  # header
    for line in f:
        parts = line.strip().split('\t')
        if parts:
            kegg_genes.add(parts[0])

print(f'KEGG-mapped genes: {len(kegg_genes)}')

# Check each gene list
for strain in ['97', '98', '99']:
    for direction in ['up', 'down']:
        fpath = f'/workspace/genes_{strain}_{direction}.txt'
        total = 0
        mapped = 0
        with open(fpath) as f:
            for line in f:
                gene = line.strip()
                if gene:
                    total += 1
                    if gene in kegg_genes:
                        mapped += 1
        print(f'{strain}_{direction}: {total} genes, {mapped} in KEGG ({100*mapped/total:.1f}%)' if total > 0 else f'{strain}_{direction}: 0 genes')

# Also check overlap between gene lists for up and down
for direction in ['up', 'down']:
    sets = {}
    for strain in ['97', '98', '99']:
        fpath = f'/workspace/genes_{strain}_{direction}.txt'
        s = set()
        with open(fpath) as f:
            for line in f:
                gene = line.strip()
                if gene and gene in kegg_genes:
                    s.add(gene)
        sets[strain] = s

    overlap_all = sets['97'] & sets['98'] & sets['99']
    print(f'{direction}: overlap all 3 strains: {len(overlap_all)} genes')
    # Some overlap pairs
    for s1, s2 in [('97','98'), ('97','99'), ('98','99')]:
        overlap = sets[s1] & sets[s2]
        print(f'  {s1}&{s2}: {len(overlap)}')
" 2>&1

