import csv

# Create combined gene lists (all |lfc| > 1.5, both directions)
for strain in ['97', '98', '99']:
    up_path = f'/workspace/genes_{strain}_up.txt'
    down_path = f'/workspace/genes_{strain}_down.txt'
    combined_path = f'/workspace/genes_{strain}_combined.txt'

    genes = set()
    for fpath in [up_path, down_path]:
        with open(fpath) as f:
            for line in f:
                g = line.strip()
                if g:
                    genes.add(g)

    with open(combined_path, 'w') as f:
        for g in sorted(genes):
            f.write(g + '\n')

    print(f'{strain}_combined: {len(genes)} genes')

# Also let's check: for each strain, look at pathways enriched in EITHER up or down
# and see if any pathway is enriched in BOTH up and down for the same strain
print()
for strain in ['97', '98', '99']:
    up_sig = set()
    down_sig = set()

    for direction in ['up', 'down']:
        fpath = f'/workspace/kegg_ora_{strain}_{direction}.tsv'
        with open(fpath) as f:
            reader = csv.DictReader(f, delimiter='\t')
            for row in reader:
                if float(row['adjusted_p_value']) < 0.05:
                    if direction == 'up':
                        up_sig.add(row['pathway_id'])
                    else:
                        down_sig.add(row['pathway_id'])

    both = up_sig & down_sig
    either = up_sig | down_sig
    print(f'{strain}: {len(up_sig)} up, {len(down_sig)} down, {len(both)} both, {len(either)} either')
    if both:
        for pid in both:
            print(f'  {pid} enriched in BOTH directions')
" 2>&1

